import{_ as s,c as o,o as e,b0 as f}from"./chunks/framework.CLL9SSSf.js";const i="/linux-driver-docs/assets/image-20260120145627337.C3luak0d.png",u=JSON.parse('{"title":"LV005-ConfigFS简介","description":null,"frontmatter":{"title":"LV005-ConfigFS简介","date":"2026-01-20T20:23:20.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/drv-base/configfs/126d2d448c50126fd9e243b7","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-20T20:23:20.294Z","fulluuid":"fd9e243b76534038a5bec5440ed7a811","useduuid":"fd9e243b7"}},"headers":[],"relativePath":"sdoc/drv-base/configfs/126d2d448c50126fd9e243b7.md","filePath":"sdoc/05-设备驱动基础/41-configfs/LV005-ConfigFS简介.md","lastUpdated":1769002717000}'),n={name:"sdoc/drv-base/configfs/126d2d448c50126fd9e243b7.md"};function r(t,a,c,l,d,p){return e(),o("div",null,[...a[0]||(a[0]=[f('<h1 id="lv005-configfs简介" tabindex="-1">LV005-ConfigFS简介 <a class="header-anchor" href="#lv005-configfs简介" aria-label="Permalink to &quot;LV005-ConfigFS简介&quot;">​</a></h1><p>前面学习设备树插件的时候有提到 ConfigFS 文件系统，它是什么？若笔记中有错误或者不合适的地方，欢迎批评指正 😃。</p><p>虚拟文件系统 ConfigFS 是一个特殊的文件系统， 旨在提供一种动态配置 Linux 内核和设备的机制。</p><h2 id="一、常用的文件系统" tabindex="-1">一、常用的文件系统 <a class="header-anchor" href="#一、常用的文件系统" aria-label="Permalink to &quot;一、常用的文件系统&quot;">​</a></h2><p>在 Linux 内核中， 有几个常用的虚拟文件系统， 虚拟文件系统提供了一个内核抽象层， 使得应用程序可以通过统一的文件访问接口操作不同类型的文件和设备。 它简化了应用程序的开发和维护， 提供了更高的可移植性和灵活性， 并提供了管理文件系统和访问底层硬件的功能。</p><h3 id="_1-procfs" tabindex="-1">1. procfs <a class="header-anchor" href="#_1-procfs" aria-label="Permalink to &quot;1. procfs&quot;">​</a></h3><p>procfs 是一个虚拟文件系统， 提供了对系统内核运行时状态的访问接口。 它以文件和目录的形式表示内核中的进程， 设备， 驱动程序和其他系统信息。 通过读取和写入 procfs 中的文件，可以获取和修改有关系统状态的信息。</p><h3 id="_2-sysfs" tabindex="-1">2. sysfs <a class="header-anchor" href="#_2-sysfs" aria-label="Permalink to &quot;2. sysfs&quot;">​</a></h3><p>sysfs 是一个虚拟文件系统， 用于表示系统中的设备， 驱动程序和其他内核对象。 它提供一种统一的接口， 通过文件和目录来访问和配置这些对象的属性和状态。 Sysfs 常用于设备驱动程序和系统管理工具， 用于查看和控制系统的硬件和内核对象。</p><h3 id="_3-configfs" tabindex="-1">3. configfs <a class="header-anchor" href="#_3-configfs" aria-label="Permalink to &quot;3. configfs&quot;">​</a></h3><p>configfs 是一个虚拟文件系统， 用于动态配置和管理内核对象。 它提供了一种以文件和目录的形式访问内核对象的接口， 允许用户在运行时添加， 修改和删除内核对象， 而无需重新编译内核或重新启动系统。 ConfigFS 常用于配置和管理设备， 驱动程序和子系统。</p><h3 id="_4-总结" tabindex="-1">4. 总结 <a class="header-anchor" href="#_4-总结" aria-label="Permalink to &quot;4. 总结&quot;">​</a></h3><p>procfs 主要用于访问和管理进程信息， 提供了有关进程， 内核参数和系统状态的信息。</p><p>sysfs 主要用于表示和配置系统中的设备， 驱动程序和其他内核对象， 提供了一种统一的接口来访问和控制这些对象的属性和状态。</p><p>configfs 主要用于动态配置和管理内核对象， 提供了一种以文件和目录的形式访问内核对象的接口， 允许在运行时添加， 修改和删除内核对象。</p><h2 id="二、设备树为什么使用-configfs" tabindex="-1">二、设备树为什么使用 configfs? <a class="header-anchor" href="#二、设备树为什么使用-configfs" aria-label="Permalink to &quot;二、设备树为什么使用 configfs?&quot;">​</a></h2><p>通过前面设备树插件的使用我们可以理出设备树的插件的实现方式， 如下图：</p><p><img src="'+i+'" alt="image-20260120145627337"></p><p>要实现上述的功能， 用户空间需要和内核进行交互， 也就是将 dtbo 加载到内存里面去。</p><p>sysfs 虚拟文件系统的作用是将内核中的数据、 属性以文件的方式导出到用户空间。 导出到用户空间以后， 读这些文件表示读取设备的文件， 写这些文件就表示控制设备。 configfs 作用的英文解释为 Userspace-driven kernel object configuration， 翻译过来就是用户空间配置内核对象</p><p>所以 configfs 与 sysfs 恰恰相反， sysfs 导出内核对象给用户空间， configfs 是从用户空间去配置内核对象， 并且不需要重新编译内核或者修改内核代码。 所以 configfs 更适合设备树插件这个技术。</p><p>选择 configfs 虚拟文件系统作为设备树插件的实现方式， 可以满足设备树插件对动态性、灵活性的需求， 使得设备树的配置和管理更加方便和高效。</p>',22)])])}const h=s(n,[["render",r]]);export{u as __pageData,h as default};
